cat > c.mjs <<'E'
import { chromium } from 'playwright';
const b=await chromium.launch();const p=await b.newPage();
await p.goto('http://127.0.0.1:63853');
await p.fill('input[type=email],input[name=email]','ops@lab.test');
await p.fill('input[type=password]','lab-ops-pass');
await p.keyboard.press('Enter');
await p.waitForTimeout(1000);
await p.goto('http://127.0.0.1:63853/refunds');
for(let pg=0;pg<6;pg++){
 const ids=await p.$$eval('tbody tr',r=>r.map(x=>({id:x.dataset.id,t:x.innerText,bl:!!x.querySelector('.badge'),st:x.querySelector('.st').innerText})));
 for(const r of ids){
  if(r.st.trim()!='Pending')continue;
  const c=r.t.split('\t');const amt=+c[3].replace(/[^\d]/g,'');
  let act=null;
  if(r.bl)act='.rj';else if(c[2].trim()=='Damaged item'&&amt<=500)act='.ap';
  console.log(pg,r.id,c[1],c[2],amt,act);
  if(act){await p.click(`tr[data-id="${r.id}"] ${act}`);await p.waitForTimeout(500);
   console.log(await p.innerText(`tr[data-id="${r.id}"] .st`).catch(()=>'gone'));}
 }
 const n=p.locator('text=Next').first();
 if(!(await n.count()))break;
 await n.click();await p.waitForTimeout(700);
 console.log(await p.innerText('text=/Page \\d of/'));
}
await b.close();
